#!/usr/bin/env python3
"""Validate the H01 JSON schema, cohort coverage and pre-change generated bytes."""
import hashlib
import json
from pathlib import Path
import sys
folder = Path(sys.argv[1])
expected = json.loads(Path('tests/eligibility_sources.json').read_text())['generatedHashes']
actual = {p.name: hashlib.sha256(p.read_bytes()).hexdigest()
          for p in (folder / 'sources').glob('*.d')}
assert actual == expected, 'generated parser bytes changed'
rows = [json.loads(line) for line in (folder / 'report.jsonl').read_text().splitlines()]
assert len(rows) == 72
assert {(r['backend'], r['memoPolicy'], r['rules'][0]['selectorConfigured']) for r in rows} == {
    (b, m, s) for b in ('combinators', 'direct') for m in ('no', 'yes', 'selective') for s in (False, True)}
for row in rows:
    assert row['grammar'] in ('Eligibility', 'Pure', 'Rec', 'Params', 'Unicode', 'Empty')
    assert isinstance(row['conservative'], bool)
    assert isinstance(row['unknownEvidence'], list) and isinstance(row['actionRules'], list)
    for rule in row['rules']:
        assert rule['name'].startswith(row['grammar'] + '.') and rule['rootExpression']
        assert isinstance(rule['scalarBlockers'], list) and isinstance(rule['directFallback'], str)
        for field in ('leftRecursive', 'memoized', 'scalarEligible', 'directRecognition',
                      'directRecords', 'selectorConfigured', 'recordSelected', 'recordLeaf', 'recordSubtree'):
            assert isinstance(rule[field], bool), field
print('72 deterministic reports: valid JSON, complete policy matrix, unchanged generated bytes.')
